DOM_SANITIZER:
()=>{
 const clone=document.documentElement.cloneNode(true);
 clone.querySelectorAll('script').forEach(n=>{if(!n.src)n.textContent='[INLINE SCRIPT REDACTED]'});
 clone.querySelectorAll('input,textarea').forEach(n=>{n.setAttribute('value','[REDACTED]');if(n.tagName==='TEXTAREA')n.textContent='[REDACTED]'});
 clone.querySelectorAll('*').forEach(n=>{for(const a of [...n.attributes]){
  if(/nonce|token|security|cart.?item.?key|cart.?hash|session/i.test(a.name))n.setAttribute(a.name,'[REDACTED]');
  else if(['href','src','action','poster'].includes(a.name)){try{const u=new URL(a.value,location.href);u.search='';u.hash='';n.setAttribute(a.name,u.href)}catch{n.setAttribute(a.name,a.value.split(/[?#]/)[0])}}
  else if(a.name==='srcset'){n.removeAttribute(a.name)}
  else if(/^on/i.test(a.name))n.setAttribute(a.name,'[INLINE HANDLER REDACTED]');
 }});
 return '<!doctype html>'+clone.outerHTML;
}
